import {
  Group,
  Mesh,
  PlaneGeometry,
  BoxGeometry,
  DirectionalLight,
  MeshStandardNodeMaterial,
  MeshPhysicalNodeMaterial,
} from 'three/webgpu';
import { texture, uv, positionLocal, normalLocal, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'stat-tile-features';

  // ---- geometry sizing (source rect 512x320 -> 1.6:1) ----
  const cardW = 1.8;
  const cardH = cardW / 1.6;
  const framePad = 0.18;
  const frameW = cardW + framePad;
  const frameH = cardH + framePad;
  const frameDepth = 0.09;

  const disposables = [];
  const primitiveHandles = [];
  const timelines = [];

  // ---- backdrop panel behind the card so it never reads as flat void ----
  const backdropGeo = new BoxGeometry(frameW + 0.3, frameH + 0.3, 0.04);
  const backdropMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.surface),
    roughness: 0.85,
    metalness: 0.1,
  });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -0.22);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---- machined metal frame ----
  const frameGeo = new BoxGeometry(frameW, frameH, frameDepth);
  const frameMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(colors.ink),
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4,
  });
  const frame = new Mesh(frameGeo, frameMat);
  frame.position.set(0, 0, -0.06);
  root.add(frame);
  disposables.push(frameGeo, frameMat);

  // ---- accent edge strip (bottom, focus indicator) ----
  const edgeGeo = new BoxGeometry(frameW * 0.7, 0.035, 0.03);
  const edgeMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.accent),
    roughness: 0.5,
    metalness: 0.2,
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 0.35,
  });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(0, -frameH / 2 + 0.03, 0.02);
  root.add(edge);
  disposables.push(edgeGeo, edgeMat);

  // ---- tessellated displacement plane (parallax-plane render mode) ----
  const planeGeo = new PlaneGeometry(cardW, cardH, 64, 64);
  const planeMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.paper),
    roughness: 0.6,
    metalness: 0.1,
  });
  const displacementScale = uniform(0.06);
  const plane = new Mesh(planeGeo, planeMat);
  plane.position.set(0, 0, 0.02);
  root.add(plane);
  disposables.push(planeGeo, planeMat);

  // ---- local rim light (accent-tinted, opposite key) ----
  const rim = new DirectionalLight(new THREE.Color(colors.accent), 0.7);
  rim.position.set(-1.2, 0.6, 1.4);
  root.add(rim);

  // ---- async texture + displacement wiring ----
  let colorTex = null;
  let depthTex = null;

  const applyNodes = () => {
    if (colorTex) {
      colorTex.colorSpace = THREE.SRGBColorSpace;
      planeMat.colorNode = texture(colorTex, uv());
    }
    if (depthTex) {
      const heightNode = texture(depthTex, uv()).r.mul(displacementScale);
      planeMat.positionNode = positionLocal.add(normalLocal.mul(heightNode));
    }
    planeMat.needsUpdate = true;
  };

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      colorTex = tex;
      applyNodes();
    });
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTex = tex;
      applyNodes();
    });
  }

  // ---- cinematic primitives from config ----
  const prims = config.cinematicPrimitives ?? [];
  for (const prim of prims) {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(root, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- entrance: weighted-settle ----
  root.scale.setScalar(0.95);
  const entranceTl = gsap.timeline();
  entranceTl.to(root.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.55,
    ease: 'power3.out',
  }).to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  timelines.push(entranceTl);

  // ---- interaction state ----
  let baseY = null;
  let hoverTl = null;
  let pressTl = null;

  const onPointerOver = () => {
    if (baseY === null) baseY = root.position.y;
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: baseY + 0.15,
      duration: 0.5,
      ease: 'power3.out',
    }, 0);
    hoverTl.to(root.rotation, {
      x: -0.05,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
    hoverTl.to(edgeMat, {
      emissiveIntensity: 1.1,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
    timelines.push(hoverTl);
  };

  const onPointerOut = () => {
    if (baseY === null) return;
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: baseY,
      duration: 0.5,
      ease: 'power3.out',
    }, 0);
    hoverTl.to(root.rotation, {
      x: 0,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
    hoverTl.to(edgeMat, {
      emissiveIntensity: 0.35,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
    timelines.push(hoverTl);
  };

  const onPointerDown = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
    });
    timelines.push(pressTl);
  };

  const onPointerUp = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.12,
      ease: 'back.out(1.7)',
    });
    timelines.push(pressTl);
  };

  const onClick = () => {
    ctx.emit('hub-features.select', { id: config.id ?? 'stat-tile-features' });
  };

  root.userData.handlers = {
    onPointerOver,
    onPointerOut,
    onPointerDown,
    onPointerUp,
    onClick,
  };

  root.userData.cleanup = () => {
    for (const tl of timelines) {
      tl.kill();
    }
    for (const handle of primitiveHandles) {
      handle.cleanup?.();
    }
    for (const item of disposables) {
      item.dispose?.();
    }
    colorTex?.dispose?.();
    depthTex?.dispose?.();
    rim.dispose?.();
  };

  return root;
}
